// The Gmail Trigger hands over each new inbox message (simple: false, so the
// parsed message with its text and HTML parts). Only what email_ingest
// (migration 049) needs travels on; the database decides whether the sender
// is someone DeskDev knows and stores nothing otherwise. Nothing here is
// logged: Summarize keeps counts only.
const EMAIL_RE = /^[^\s@,;<>"']+@[^\s@,;<>"']+\.[^\s@,;<>"']+$/;
const MAX_BODY = 50000;

// mailparser shape: { value: [{ address, name }], text }, or an array of them
// when a header appears twice.
const entries = (field) => {
  if (!field) return [];
  const groups = Array.isArray(field) ? field : [field];
  return groups.flatMap(g => (g && Array.isArray(g.value) ? g.value : []));
};
const addresses = (field) => [...new Set(entries(field)
  .map(a => String((a && a.address) || '').trim().toLowerCase())
  .filter(a => EMAIL_RE.test(a)))].slice(0, 10);

const stripHtml = (html) => String(html || '')
  .replace(/<(script|style|head)\b[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|li|tr|h[1-6]|blockquote)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
  .replace(/&amp;/gi, '&')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n[ \t]+/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// The thread already lives in DeskDev, so the quoted history under a reply is
// cut ("On … wrote:", Outlook's "-----Original Message-----" / From:+Sent:).
// Only when something is left above it; otherwise the text is kept whole.
const withoutQuote = (text) => {
  const t = String(text || '').replace(/\r\n?/g, '\n');
  const marks = [
    /\n[ \t>]*On [^\n]{3,300}?(?:\n[^\n]{0,300}?)?wrote:[ \t]*(?:\n|$)/,
    /\n[ \t]*-{2,}[ \t]*Original Message[ \t]*-{2,}/i,
    /\n[ \t]*_{8,}[ \t]*\n[ \t]*From:/,
    /\n[ \t]*From:[^\n]*\n[ \t]*(?:Sent|Date):/,
  ];
  let cut = -1;
  for (const re of marks) {
    const m = t.match(re);
    if (m && (cut === -1 || m.index < cut)) cut = m.index;
  }
  const kept = cut > 0 ? t.slice(0, cut).trim() : '';
  return kept || t.trim();
};

const out = [];
for (const item of $input.all()) {
  const m = item.json || {};
  const from = entries(m.from)[0] || {};
  const fromEmail = String(from.address || '').trim().toLowerCase();
  if (!m.id || !EMAIL_RE.test(fromEmail)) continue;
  const text = typeof m.text === 'string' && m.text.trim() ? m.text : stripHtml(m.html);
  const received = new Date(m.date || Number(m.internalDate) || Date.now());
  out.push({ json: {
    gmail_message_id: String(m.id),
    gmail_thread_id: m.threadId ? String(m.threadId) : null,
    from_email: fromEmail,
    from_name: String(from.name || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 120),
    to_emails: addresses(m.to),
    cc_emails: addresses(m.cc),
    subject: String(m.subject || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 300),
    body_text: withoutQuote(text).slice(0, MAX_BODY),
    received_at: Number.isNaN(received.getTime()) ? new Date().toISOString() : received.toISOString(),
  } });
}
return out;

// One run-log row per poll that found mail: counts only, never addresses,
// subjects or text. email_ingest answers {ok, matched, duplicate?, reason?};
// a call that failed (Ingest continues on error) carries `error` instead.
const results = $('Ingest').all().map(i => i.json || {});
const seen = $('New mail').all().length;
let matched = 0;
let duplicates = 0;
let ignored = 0;
let failed = 0;
for (const r of results) {
  if (r.error || r.ok !== true) failed++;
  else if (r.duplicate) duplicates++;
  else if (r.matched) matched++;
  else ignored++;
}
// No message id or no readable sender: never sent to the database.
const skipped = Math.max(0, seen - results.length);
// Every call failing means the database is not answering (or 049 is missing).
const status = results.length > 0 && failed === results.length ? 'error' : 'ok';
return [{ json: { status, detail: { seen, matched, duplicates, ignored, skipped, failed } } }];
